begin;
set local lock_timeout='5s';set local statement_timeout='90s';
create table public.places_marketing_events(id uuid primary key,property_id uuid not null references public.places_properties(id) on delete restrict,event_type text not null check(event_type in('PAGE_VIEW','PREMIUM_CTA')),session_key text not null check(session_key ~ '^[a-f0-9]{64}$'),source text not null check(source in('DIRECT_UNKNOWN','SHIAP','SEARCH','SOCIAL','OTHER')),created_at timestamptz not null default now());
create index places_marketing_property_date_idx on public.places_marketing_events(property_id,created_at desc);
alter table public.places_marketing_events enable row level security;revoke all on public.places_marketing_events from public,anon,authenticated;grant all on public.places_marketing_events to service_role;
create function public.server_record_places_marketing(p_id uuid,p_property_id uuid,p_event text,p_session text,p_source text) returns void language plpgsql security definer set search_path='' as $$declare old public.places_marketing_events%rowtype;begin
 if p_id is null or p_property_id is null or p_event is null or p_event not in('PAGE_VIEW','PREMIUM_CTA') or p_session is null or p_session !~ '^[a-f0-9]{64}$' or p_source is null or p_source not in('DIRECT_UNKNOWN','SHIAP','SEARCH','SOCIAL','OTHER') then raise exception 'Invalid marketing event' using errcode='22023';end if;
 if not shiap_private.places_premium_visible(p_property_id) or not exists(select 1 from public.places_profile_publications where property_id=p_property_id) then return;end if;
 select * into old from public.places_marketing_events where id=p_id;if found then if old.property_id<>p_property_id or old.event_type<>p_event or old.session_key<>p_session then raise exception 'Event conflict' using errcode='PT409';end if;return;end if;
 insert into public.places_marketing_events(id,property_id,event_type,session_key,source) values(p_id,p_property_id,p_event,p_session,p_source) on conflict(id) do nothing;end$$;
revoke all on function public.server_record_places_marketing(uuid,uuid,text,text,text) from public,anon,authenticated;grant execute on function public.server_record_places_marketing(uuid,uuid,text,text,text) to service_role;
create function public.partner_places_analytics(p_property_id uuid,p_days integer default 30) returns jsonb language plpgsql stable security definer set search_path='' as $$declare result jsonb;sources jsonb;begin
 if auth.uid() is null or not(public.is_shiap_admin() or shiap_private.places_member(p_property_id,false)) then raise exception 'Property access required.' using errcode='42501';end if;
 if p_days is null or p_days not in(7,30) then raise exception 'Select 7 or 30 days.' using errcode='22023';end if;
 select jsonb_object_agg(period,metrics) into result from(select period,jsonb_build_object('page_views',(select count(*) from public.places_marketing_events where property_id=p_property_id and event_type='PAGE_VIEW' and created_at>=start_at and created_at<end_at),'browser_sessions',(select count(distinct session_key) from public.places_marketing_events where property_id=p_property_id and event_type='PAGE_VIEW' and created_at>=start_at and created_at<end_at),'cta_clicks',(select count(*) from public.places_marketing_events where property_id=p_property_id and event_type='PREMIUM_CTA' and created_at>=start_at and created_at<end_at),'leads',(select count(*) from public.places_contact_leads where property_id=p_property_id and deleted_at is null and created_at>=start_at and created_at<end_at),'handoffs',(select count(*) from public.places_contact_leads where property_id=p_property_id and deleted_at is null and status='HANDOFF_INITIATED' and created_at>=start_at and created_at<end_at)) metrics from(values('current',now()-make_interval(days=>p_days),now()),('previous',now()-make_interval(days=>p_days*2),now()-make_interval(days=>p_days))) windows(period,start_at,end_at))q;
 select coalesce(jsonb_object_agg(source,n),'{}') into sources from(select source,count(*) n from public.places_marketing_events where property_id=p_property_id and event_type='PAGE_VIEW' and created_at>=now()-make_interval(days=>p_days) group by source)x;
 return result||jsonb_build_object('sources',sources,'days',p_days,'retention_days',90);end$$;
revoke all on function public.partner_places_analytics(uuid,integer) from public,anon;grant execute on function public.partner_places_analytics(uuid,integer) to authenticated;
create function public.admin_erase_places_marketing(p_property_id uuid,p_confirm boolean) returns void language plpgsql security definer set search_path='' as $$begin if auth.uid() is null or not public.is_shiap_admin() then raise exception 'Admin required' using errcode='42501';end if;if p_confirm is distinct from true then raise exception 'Confirmation required' using errcode='22023';end if;delete from public.places_marketing_events where property_id=p_property_id;insert into public.places_partner_audit_logs(property_id,actor_id,event) values(p_property_id,auth.uid(),'ANALYTICS_ERASED');end$$;
revoke all on function public.admin_erase_places_marketing(uuid,boolean) from public,anon;grant execute on function public.admin_erase_places_marketing(uuid,boolean) to authenticated;
-- Retention uses the already authenticated scheduler, no second job or Node timer.
alter function public.notification_schedule() set schema shiap_private;alter function shiap_private.notification_schedule() rename to notification_business_schedule_v1;
create function public.notification_schedule() returns void language plpgsql security invoker set search_path='' as $$begin perform shiap_private.notification_business_schedule_v1();delete from public.places_marketing_events where created_at<now()-interval '90 days';end$$;
revoke all on function public.notification_schedule() from public,anon,authenticated;grant execute on function public.notification_schedule() to service_role;
commit;
